//! Descrições das ferramentas internas em inglês (a tabela principal, em tools.rs, é constante e fica em
//! português). Com o studio em inglês, o modelo recebe estas.

/// (descrição, esquema dos parâmetros) em inglês, pelo nome da ferramenta.
pub fn def_en(name: &str) -> Option<(&'static str, &'static str)> {
    Some(match name {
        "list_directory" => ("Lists files and folders. The path is relative to the workspace (use \".\" for the root). Also accepts absolute paths the user referenced.",
            r#"{"type":"object","properties":{"path":{"type":"string","description":"Folder path"}},"required":["path"]}"#),
        "analyze_image" => ("Looks at an image in the project and answers about it (screenshot, photo, diagram, error print). A vision model does the looking, in a queue that switches automatically if one fails; you get the text. Use it whenever you need to know what is in an image.",
            r#"{"type":"object","properties":{"path":{"type":"string","description":"Image: path in the project (or absolute) of a png, jpg, gif, webp or bmp"},"question":{"type":"string","description":"What you want to know (e.g. \"what error shows?\", \"transcribe the code\", \"where is the Save button?\"). Empty = full description"}},"required":["path"]}"#),
        "read_file" => ("Reads a text file. A large file without offset/limit comes back as an outline (sections, headings, functions) with line numbers: then read only the parts you need with offset/limit.",
            r#"{"type":"object","properties":{"path":{"type":"string"},"offset":{"type":"integer","description":"First line (1 = first)"},"limit":{"type":"integer","description":"Maximum number of lines"}},"required":["path"]}"#),
        "search_files" => ("Searches files by name (accepts * as a wildcard) and, optionally, by content (regular expression). Returns relative paths and, when searching content, the matching lines with their numbers. path can be a file: searches only in it.",
            r#"{"type":"object","properties":{"name":{"type":"string","description":"Part of the name or a pattern, e.g.: *.py"},"content":{"type":"string","description":"Regex to search inside the files"},"path":{"type":"string","description":"Folder (or file) to search in (default: root)"}}}"#),
        "write_file" => ("Creates or replaces a file inside the workspace with the given content. Creates missing folders. To change part of an existing file, use edit_file (much cheaper).",
            r#"{"type":"object","properties":{"path":{"type":"string"},"content":{"type":"string"}},"required":["path","content"]}"#),
        "create_directory" => ("Creates a folder (and the ones in between) inside the workspace.",
            r#"{"type":"object","properties":{"path":{"type":"string"}},"required":["path"]}"#),
        "edit_file" => ("Changes part of a file. Three ways: old_text + new_text (exact old_text, appearing once, or replace_all); start_line + end_line + new_text (replaces those lines without repeating the old text; end_line = start_line - 1 inserts before; send expect with the start of line start_line); or edits = list of {old_text, new_text} applied together.",
            r#"{"type":"object","properties":{"path":{"type":"string"},"old_text":{"type":"string"},"new_text":{"type":"string"},"replace_all":{"type":"boolean"},"start_line":{"type":"integer"},"end_line":{"type":"integer"},"expect":{"type":"string","description":"With start_line: the start of line start_line as it is now (checks the number did not change)"},"edits":{"type":"array","items":{"type":"object","properties":{"old_text":{"type":"string"},"new_text":{"type":"string"}},"required":["old_text","new_text"]}}},"required":["path"]}"#),
        "run_command" => ("Runs a PowerShell (Windows) command inside the workspace and returns the output and the exit code. Use it to build, run scripts, git, install packages etc. Do not use it for interactive commands.",
            r#"{"type":"object","properties":{"command":{"type":"string","description":"PowerShell command or script"},"cwd":{"type":"string","description":"Subfolder to run in (default: workspace root)"},"timeout":{"type":"integer","description":"Seconds until it is stopped (default 120, maximum 1800)"}},"required":["command"]}"#),
        "execute_code" => ("Runs (async) JavaScript to orchestrate several tools at once, without filling the context with intermediate results. Inside the code: `await tool('tool_name', {arguments})` returns the result text (throws if the tool fails); `console.log(...)` logs; `return value` returns the final result. E.g.: loops over files, filtering results, calling several tools and summarizing.",
            r#"{"type":"object","properties":{"code":{"type":"string","description":"Body of an async JavaScript function"}},"required":["code"]}"#),
        "browser_navigate" => ("Opens a URL in the browser window controlled by the studio and returns the page text and the numbered interactive elements.",
            r#"{"type":"object","properties":{"url":{"type":"string"}},"required":["url"]}"#),
        "browser_read" => ("Reads the current browser page: title, URL, text and numbered interactive elements.", r#"{"type":"object","properties":{}}"#),
        "browser_click" => ("Clicks a page element by the number shown in browser_read/browser_navigate.",
            r#"{"type":"object","properties":{"id":{"type":"integer"}},"required":["id"]}"#),
        "browser_type" => ("Types into a page field (by its number). Replaces the current content. Use submit=true to press Enter afterwards.",
            r#"{"type":"object","properties":{"id":{"type":"integer"},"text":{"type":"string"},"submit":{"type":"boolean"}},"required":["id","text"]}"#),
        "browser_press" => ("Presses a key on the page: Enter, Tab, Escape, Backspace, ArrowDown, ArrowUp, PageDown or PageUp.",
            r#"{"type":"object","properties":{"key":{"type":"string"}},"required":["key"]}"#),
        "browser_back" => ("Goes back to the previous page.", r#"{"type":"object","properties":{}}"#),
        "browser_screenshot" => ("Takes a screenshot of the current page (saved in the screenshots folder). If the model can see images, the image is sent to it.", r#"{"type":"object","properties":{}}"#),
        "browser_eval" => ("Runs JavaScript on the open page and returns the result (JSON).",
            r#"{"type":"object","properties":{"code":{"type":"string","description":"Expression or immediately invoked function"}},"required":["code"]}"#),
        "computer_windows" => ("Lists the windows open on the user's computer (id and title).", r#"{"type":"object","properties":{}}"#),
        "computer_focus" => ("Brings a window to the foreground, by id or part of the title.",
            r#"{"type":"object","properties":{"window":{"type":"string","description":"id or part of the title"}},"required":["window"]}"#),
        "computer_elements" => ("Lists the screen elements (buttons, fields, menus, texts) of a window through Windows UI Automation, numbered for computer_click. Without window, uses the foreground window.",
            r#"{"type":"object","properties":{"window":{"type":"string","description":"id or part of the title (optional)"},"filter":{"type":"string","description":"Only elements containing this text (optional)"}}}"#),
        "computer_screenshot" => ("Captures the whole screen (saved in the screenshots folder). If the model can see images, the image is sent to it.", r#"{"type":"object","properties":{}}"#),
        "computer_click" => ("Clicks an element (id from computer_elements) or a point (x, y from the last screenshot). button: left or right. double: double click.",
            r#"{"type":"object","properties":{"id":{"type":"integer"},"x":{"type":"integer"},"y":{"type":"integer"},"button":{"type":"string","enum":["left","right"]},"double":{"type":"boolean"}}}"#),
        "computer_type" => ("Types text where the cursor is (in the foreground window).",
            r#"{"type":"object","properties":{"text":{"type":"string"}},"required":["text"]}"#),
        "computer_key" => ("Presses a key or combination, e.g.: enter, ctrl+s, alt+f4, ctrl+shift+esc, win+r.",
            r#"{"type":"object","properties":{"keys":{"type":"string"}},"required":["keys"]}"#),
        "computer_scroll" => ("Scrolls the mouse wheel. Negative amount scrolls down, positive scrolls up. x and y optional (from the last screenshot).",
            r#"{"type":"object","properties":{"amount":{"type":"integer"},"x":{"type":"integer"},"y":{"type":"integer"}},"required":["amount"]}"#),
        "recall_history" => ("Searches earlier chats (or only the current one) for passages about a subject. Use it when the user refers to something already discussed.",
            r#"{"type":"object","properties":{"query":{"type":"string"},"scope":{"type":"string","enum":["all","current"]},"limit":{"type":"integer"}},"required":["query"]}"#),
        "notebook" => ("Project notebook with lasting findings. list (optional query), get (id), add (title), update (id + fields), remove (id).",
            r#"{"type":"object","properties":{"action":{"type":"string","enum":["list","get","add","update","remove"]},"query":{"type":"string"},"id":{"type":"integer"},"title":{"type":"string"},"kind":{"type":"string","description":"function, address, string, hypothesis..."},"addr":{"type":"string","description":"e.g.: 0x401000"},"status":{"type":"string","enum":["hypothesis","confirmed","discarded"]},"text":{"type":"string"}},"required":["action"]}"#),
        "update_todos" => ("Keeps this chat's task list, visible to the user. Use it for tasks with 3 or more steps: create the list at the start and update it when starting (in_progress) and finishing (done) each item. Always send the whole list; only one item in_progress at a time.",
            r#"{"type":"object","properties":{"todos":{"type":"array","items":{"type":"object","properties":{"text":{"type":"string","description":"What to do, short and in the imperative"},"status":{"type":"string","enum":["pending","in_progress","done"]}},"required":["text","status"]}}},"required":["todos"]}"#),
        "search_tools" => ("MCP connector tools. query: searches by keywords and shows name and description (does not load). names: loads these (exact names) for the next steps.",
            r#"{"type":"object","properties":{"names":{"type":"array","items":{"type":"string"},"description":"Exact names from the catalog"},"query":{"type":"string","description":"Keywords"}}}"#),
        "explore" => ("Starts an explorer subagent: it investigates on its own (read only: files, search and, if on, the browser) with its own context and returns a report. Use it for broad research without filling your context. Call it several times in the same answer to explore in parallel.",
            r#"{"type":"object","properties":{"task":{"type":"string","description":"What to investigate and what the report must contain"},"where":{"type":"string","description":"Folder, files or site to start with (optional)"}},"required":["task"]}"#),
        "video_edit" => ("Edits real project videos (files in public/) through an edit list: clips with start and end, layout (vertical crop, react with facecam on top, corner window, side by side), transitions, zoom, speed, filters, texts, overlays (emoji, image, arrow, circle), animated captions that follow the cuts, and music. A facecam baked into the recording can go on top (cam with crop) and the crop can follow the action (focusX \"auto\"). It can remove the pauses by itself using the captions (cutSilences). The studio checks files and times, builds the <name> composition from a ready template (do not write React to edit), registers it in Root.tsx and tests it. Use video_look and video_find first to choose the times. For animations from scratch, use video_scenes.",
            r#"{"type":"object","properties":{"name":{"type":"string","description":"Composition name in PascalCase (e.g. Cut1, ReactShorts). Same name = replaces the previous list"},"edl":{"type":"object","properties":{"format":{"type":"string","enum":["9:16","16:9","1:1","4:5"]},"fps":{"type":"integer","description":"Default 30"},"clips":{"type":"array","description":"Clips in the order they appear","items":{"type":"object","properties":{"src":{"type":"string","description":"File in public/, e.g. recording.mp4"},"from":{"type":["number","string"],"description":"Start in the file in SECONDS (e.g. 175.5) or text \"2:55.5\"; never 2.55 for 2:55"},"to":{"type":["number","string"],"description":"End in the file, same as from"},"layout":{"type":"string","enum":["full","fit","react","pip","side"],"description":"full: fills by cropping (use focusX/focusY to pick the area); fit: whole video over a blurred background; react: cam on top and the video below; pip: cam in a corner window; side: side by side"},"cam":{"type":"object","description":"Second video (facecam) for react/pip/side, in sync with the clip. Facecam baked into the recording itself: omit src and pass crop with its region (e.g. {\"x\":0.72,\"y\":0.62,\"w\":0.26,\"h\":0.36}); find the region with video_look.","properties":{"src":{"type":"string","description":"File in public/; empty = the clip's own file (use with crop)"},"from":{"type":["number","string"],"description":"Where the cam starts (seconds or \"m:ss\") when the clip starts; empty = in sync (same file) or 0"},"volume":{"type":"number"},"focusX":{"type":"number"},"focusY":{"type":"number"},"crop":{"type":"object","description":"Frame region as 0..1 fractions: x,y = top-left corner; w,h = width and height","properties":{"x":{"type":"number"},"y":{"type":"number"},"w":{"type":"number"},"h":{"type":"number"}},"required":["x","y","w","h"]}},"required":[]},"split":{"type":"number","description":"react: fraction of the height for the cam (default 0.5); pip: window width (default 0.3)"},"corner":{"type":"string","enum":["tl","tr","bl","br"]},"focusX":{"type":["number","string"],"description":"0..1, horizontal center of the crop (0.5 = middle), or \"auto\": the crop follows the scene's motion through the clip"},"focusY":{"type":"number"},"speed":{"type":"number","description":"0.25 to 4"},"volume":{"type":"number","description":"0 to 2"},"mute":{"type":"boolean"},"filter":{"type":"string","enum":["none","bw","warm","cold","vivid","dark"]},"zoom":{"type":"number","description":"Slow zoom up to this scale at the end of the clip (e.g. 1.1)"},"punch":{"type":"array","description":"Quick emphasis zoom","items":{"type":"object","properties":{"at":{"type":"number","description":"s from the start of the clip"},"scale":{"type":"number"},"dur":{"type":"number"}},"required":["at"]}},"transition":{"type":"string","enum":["cut","fade","slide","wipe","zoom"],"description":"How this clip comes in"},"transitionDur":{"type":"number","description":"s (default 0.5)"},"texts":{"type":"array","items":{"type":"object","properties":{"text":{"type":"string"},"at":{"type":"number","description":"s from the start of the clip"},"dur":{"type":"number"},"pos":{"type":"string","enum":["top","center","bottom"]},"style":{"type":"string","enum":["title","label","thumb"],"description":"thumb: huge, yellow with outline (thumbnail)"}},"required":["text","at","dur"]}},"cutSilences":{"type":"boolean","description":"Removes this clip's pauses using the captions (needs video_captions first)"},"crop":{"type":"object","description":"Uses only this region of the recording (e.g. only the game area, without the baked-in facecam); 0..1 fractions","properties":{"x":{"type":"number"},"y":{"type":"number"},"w":{"type":"number"},"h":{"type":"number"}},"required":["x","y","w","h"]},"overlays":{"type":"array","description":"On top of the video at an instant: emoji, image from public/ (meme, logo), arrow or highlight circle","items":{"type":"object","properties":{"kind":{"type":"string","enum":["emoji","image","arrow","circle"]},"text":{"type":"string","description":"emoji: the emoji"},"src":{"type":"string","description":"image: file in public/"},"at":{"type":"number","description":"s from the start of the clip"},"dur":{"type":"number"},"x":{"type":"number","description":"Center on the final screen, 0..1 (0 = left)"},"y":{"type":"number","description":"0..1 (0 = top)"},"size":{"type":"number","description":"Fraction of the screen width (default 0.25)"},"angle":{"type":"number","description":"arrow: where it points in degrees (0 = right, 90 = down)"},"color":{"type":"string"},"anim":{"type":"string","enum":["pop","shake","none"]}},"required":["kind","at","dur","x","y"]}}},"required":["src","from","to"]}},"cutSilences":{"type":"boolean","description":"Removes the pauses of every clip"},"minSilence":{"type":"number","description":"Shortest pause that is cut, in s (default 0.6)"},"captions":{"type":"object","description":"Animated captions from public/captions/ (they follow the cuts)","properties":{"style":{"type":"string","enum":["tiktok","line","none"]},"source":{"type":"string","enum":["main","cam"]},"pos":{"type":"string","enum":["bottom","center","top"]},"color":{"type":"string"},"highlight":{"type":"string"}}},"music":{"type":"object","properties":{"src":{"type":"string"},"volume":{"type":"number","description":"Default 0.15"},"from":{"type":"number"}},"required":["src"]},"background":{"type":"string"}},"required":["clips"]}},"required":["name","edl"]}"#),
        "video_peaks" => ("Volume peaks in the audio of a project video: gunshots, explosions, hits, shouts and laughs, which the captions miss. Returns the loud stretches (nearby peaks grouped: a firefight becomes one stretch with several peaks), strongest first, with the second of the peak and how many dB above normal, plus each minute's volume. Fast (a few seconds): use it before sweeping the video with video_look and confirm each stretch by looking.",
            r#"{"type":"object","properties":{"file":{"type":"string","description":"File in public/"},"from":{"type":"number","description":"Start in seconds (default 0)"},"to":{"type":"number","description":"End in seconds (default: the end)"},"min":{"type":"number","description":"How many dB above normal counts as a peak (default 8; 12 = only the very loud ones)"},"top":{"type":"integer","description":"How many stretches to return (default 15, max 40)"}},"required":["file"]}"#),
        "video_thumbnail" => ("Video thumbnail: one frame of the recording with big text on top, optional emojis and arrows. Makes out/<name>.png (full-size PNG) and returns the image for you to check. Pick the frame first with video_look.",
            r#"{"type":"object","properties":{"name":{"type":"string","description":"PascalCase name (e.g. ThumbCut1); saved as out/<name>.png"},"src":{"type":"string","description":"Video in public/"},"at":{"type":["number","string"],"description":"Second of the frame in the file (or \"m:ss\"): pick an expressive face or the peak of the action with video_look"},"text":{"type":"string","description":"Big text, up to 4 words (yellow with outline)"},"sub":{"type":"string","description":"Optional smaller text, on a band"},"pos":{"type":"string","enum":["top","center","bottom"]},"format":{"type":"string","enum":["9:16","16:9","1:1","4:5"],"description":"Default 9:16 (Shorts); 16:9 for YouTube"},"layout":{"type":"string","enum":["full","fit"]},"focusX":{"type":"number"},"focusY":{"type":"number"},"crop":{"type":"object","properties":{"x":{"type":"number"},"y":{"type":"number"},"w":{"type":"number"},"h":{"type":"number"}},"required":["x","y","w","h"],"description":"Frame region (0..1 fractions)"},"zoom":{"type":"number","description":"Zooms into the frame (e.g. 1.3)"},"filter":{"type":"string","enum":["none","bw","warm","cold","vivid","dark"]},"overlays":{"type":"array","description":"Emoji, image, arrow or circle, as in video_edit","items":{"type":"object","properties":{"kind":{"type":"string","enum":["emoji","image","arrow","circle"]},"text":{"type":"string"},"src":{"type":"string"},"x":{"type":"number"},"y":{"type":"number"},"size":{"type":"number"},"angle":{"type":"number"},"color":{"type":"string"}},"required":["kind","x","y"]}}},"required":["name","src","at","text"]}"#),
        "video_find" => ("What is said in a project video or audio file, phrase by phrase with each one's time, plus the pauses, from the captions (generate them with video_captions first). With query, only the phrases with those words (e.g. \"wow|no way|oh my god|lol\"): the quick way to find reactions, screams and jokes in a long stream. Use from/to to see a part.",
            r#"{"type":"object","properties":{"file":{"type":"string","description":"File in public/"},"from":{"type":"number"},"to":{"type":"number"},"query":{"type":"string","description":"Words to search, separated by | (works without accents too)"},"gap":{"type":"number","description":"Shortest pause that separates phrases, in s (default 0.6)"}},"required":["file"]}"#),
        "video_check" => ("Checks the project video after editing: types (tsc) and a run test that renders one frame per second at minimal size, catching errors that only show up when running (interpolate with an out-of-order range, an undefined value, a public/ file that does not exist). Returns the error with the scene, frame and line.",
            r#"{"type":"object","properties":{"composition":{"type":"string","description":"Default: Video"}}}"#),
        "video_look" => ("Looks at a project video: grabs evenly spaced frames (with each one's time) and returns them as an image, along with the speech in that stretch if the video already has captions. Use it to find where to cut, what shows in each part, whether a scene turned out well. To see a render, pass out/<Composition> (e.g. out/CutOfTheVideo): the studio finds the latest one (files are saved as out/<Composition>-<date>.mp4).",
            r#"{"type":"object","properties":{"file":{"type":"string","description":"Path in the project, e.g. public/recording.mp4 or out/Video-20261109.mp4"},"from":{"type":"number","description":"Start of the stretch in seconds (default 0)"},"to":{"type":"number","description":"End of the stretch in seconds (default: the end of the video)"},"count":{"type":"integer","description":"How many frames (default 12, max 24)"}},"required":["file"]}"#),
        "video_captions" => ("Generates captions from the audio of a project video or audio file with Whisper, on this PC. Saves public/captions/<name>.json (list of words with startMs/endMs, the @remotion/captions Caption format) and .srt. The first time it downloads Whisper and the speech model (150 MB to 1.6 GB); it can take a few minutes.",
            r#"{"type":"object","properties":{"file":{"type":"string","description":"Path in the project, e.g. public/interview.mp4"},"language":{"type":"string","description":"Language code (pt, en, es...); empty = detect"},"model":{"type":"string","enum":["base","small","medium","large-v3-turbo"],"description":"Default small (good for Portuguese). medium and large-v3-turbo are more accurate and slower"}},"required":["file"]}"#),
        "video_scenes" => ("Remotion video as a team: you pass the shared style and the list of scenes (in order, with duration and description) and each scene is written in parallel by a subagent (the team's APIs), in src/scenes/<Name>.tsx. Then the studio assembles the sequence (src/scenes/Video.tsx), registers the \"Video\" composition in src/Root.tsx, checks the types and sends the errors back to whoever wrote each scene. Always send the full list in order; to redo only some, pass their names in only.",
            r#"{"type":"object","properties":{"style":{"type":"string","description":"What applies to every scene: palette (hex colors), fonts, pace, mood, recurring elements"},"fps":{"type":"integer","description":"Default 30"},"width":{"type":"integer","description":"Default 1920"},"height":{"type":"integer","description":"Default 1080"},"scenes":{"type":"array","items":{"type":"object","properties":{"name":{"type":"string","description":"Component name in PascalCase, e.g. Intro"},"seconds":{"type":"number","description":"Scene duration"},"description":{"type":"string","description":"What appears, exact texts, animations and how it ends (to flow into the next one)"}},"required":["name","seconds","description"]}},"only":{"type":"array","items":{"type":"string"},"description":"Optional: redo only these scenes (the others stay as they are)"}},"required":["style","scenes"]}"#),
        "multi_explore" => ("Fires several explorer subagents in parallel from a main task. Pass the overall goal and a list of subtasks, each with its own scope. Each agent investigates on its own (read + browser) and returns a report; the consolidated result joins them all.",
            r#"{"type":"object","properties":{"task":{"type":"string","description":"Main task / overall investigation goal"},"subtasks":{"type":"array","items":{"type":"object","properties":{"task":{"type":"string","description":"What this agent must investigate"},"where":{"type":"string","description":"Folder, files or site to start with (optional)"}},"required":["task"]},"description":"List of subtasks, one per parallel agent"},"maxConcurrentExplorers":{"type":"integer","minimum":1,"description":"Maximum number of agents to run at once (defaults to config setting)"}},"required":["task","subtasks"]}"#),
        "read_skill_file" => ("Reads a helper file of an active skill (scripts, templates, references cited in SKILL.md). A large file comes back as an outline; read parts with offset/limit.",
            r#"{"type":"object","properties":{"skill":{"type":"string","description":"skill id"},"path":{"type":"string"},"offset":{"type":"integer"},"limit":{"type":"integer"}},"required":["skill","path"]}"#),
        "customize_ui" => ("Personalize the interface: themes (colors, fonts), layouts, and custom widgets. Creates and applies visualization settings.",
            r#"{"type":"object","properties":{"theme":{"type":"string","description":"Theme name (light, dark, custom)"}, "colors":{"type":"object","description":"Custom colors: background, foreground, accent, primary, secondary, warning, error, success"}, "fonts":{"type":"object","description":"Fonts: body, monospace, header"}, "layout":{"type":"string","description":"Layout: compact, spacious, grid, list"}, "widgets":{"type":"array","items":{"type":"string","description":"Widgets: statusbar, toolbar, sidebar, panels, tabs"}}},"required":[]}"#),
        _ => return None,
    })
}

#[cfg(test)]
mod t {
    #[test]
    fn esquemas_validos() {
        for n in ["analyze_image", "video_edit", "video_peaks", "video_thumbnail", "video_find", "video_check", "video_look", "video_captions", "video_scenes", "list_directory", "read_file", "search_files", "write_file", "create_directory", "edit_file", "run_command", "execute_code", "browser_navigate", "browser_read", "browser_click", "browser_type", "browser_press", "browser_back", "browser_screenshot", "browser_eval", "computer_windows", "computer_focus", "computer_elements", "computer_screenshot", "computer_click", "computer_type", "computer_key", "computer_scroll", "recall_history", "notebook", "update_todos", "search_tools", "explore", "multi_explore", "read_skill_file", "customize_ui"] {
            let (_, p) = super::def_en(n).unwrap_or_else(|| panic!("sem inglês: {n}"));
            serde_json::from_str::<serde_json::Value>(p).unwrap_or_else(|e| panic!("{n}: {e}"));
        }
    }
}
